--PAYMENTS

CREATE TABLE Payments (
    payment_id INT AUTO_INCREMENT PRIMARY KEY,
    bill_id INT,
    payment_date DATE,
    payment_method ENUM('Cash','Card','UPI','Net Banking'),
    amount_paid DECIMAL(10,2),
    transaction_id VARCHAR(100),
    FOREIGN KEY (bill_id)
    REFERENCES Billing(bill_id));

