--QUERIES
Basic Queries 
1.Display all details of all patients.
select * from patients;

2.Display only patient names and blood groups from the Patients table.
select patient_name,blood_group from patients;

3.Find all male patients.
select * from patients where gender="male";

4.Find all female patients whose blood group is 'A+'.
select * from patients where gender="female" and blood_group="A+";

5.Display doctors with their specialization and consultation fee.
select specialization,consultation_fee from doctors; 

6.Find all doctors having more than 10 years of experience.
select * from doctors where experience> 10;

7.Display all available rooms.
select * from rooms where status="available";

8.Display all medicines with stock quantity less than 50.
select * from medicines where stock_quantity <50;

9.Find medicines whose expiry date is before '2026-01-01'.
select * from medicines where expiry_date < '2026-01-01';

10.Display all appointments scheduled for a particular date.
select * from appointments where appointment_date='2025-01-28';

11.Display patients in alphabetical order by patient name.
select * from patients order by patient_name asc;

12.Display doctors with the highest consultation fee first.
select * from doctors order by consultation_fee desc;

13.Display rooms floor-wise in ascending order.
select * from rooms order by floor asc;

14.Find patients born after the year 2000.
select * from patients where dob >'2000-12-31';

15.Display all completed appointments.
select * from appointments where status="completed";

16.Find the total number of patients in the hospital.
select count(*) from patients;

17.Find the total number of doctors available.
select count(*) from doctors;

18.Find the average consultation fee of doctors.
select avg(consultation_fee) from doctors;

19.Find the maximum and minimum medicine price.
select max(unit_price),min(unit_price) from medicines;

20.Find the total billing amount generated by the hospital.
select sum(total_amount) as total_amount from billing;

21.Count the number of patients based on blood group.
select blood_group,count(patient_id) from patients group by blood_group;

22.Find the number of doctors in each department.
SELECT d.department_name,COUNT(doc.doctor_id) AS total_doctors FROM Departments as d
inner join doctors as doc on  d.department_id = doc.department_id
group by d.department_id, d.department_name order by total_doctors desc;

23.Find the number of rooms based on room type.
select room_type,count(room_number) from rooms group by room_type order by count(room_number)desc;

24.Find the total medicines available by manufacturer.
select manufacturer ,count(medicine_name) from medicines group by manufacturer;

25.Find the number of appointments handled by each doctor.
SELECT d.doctor_id,d.doctor_name,COUNT(a.appointment_id) AS total_appointments
FROM Doctors d inner join Appointments a
ON d.doctor_id = a.doctor_id GROUP BY d.doctor_id,d.doctor_name
ORDER BY total_appointments desc;

26.Find departments having more than 5 doctors.
SELECT d.department_id,d.department_name,COUNT(doc.doctor_id) AS total_doctors
FROM Departments as d JOIN Doctors as doc ON d.department_id = doc.department_id
GROUP BY d.department_id, d.department_name HAVING COUNT(doc.doctor_id) > 5 
ORDER BY total_doctors DESC;

27.Find doctors who have completed more than 10 appointments.
select doc.doctor_id,doc.doctor_name ,count(a.appointment_id) as completed_appointments from doctors as doc 
inner join appointments as a on doc.doctor_id=a.doctor_id where a.status="completed"
group by doc.doctor_name,doc.doctor_id having count(a.appointment_id)>10 order by completed_appointments;

28.Find blood groups having more than 100 patients.
select p.blood_group,count(*) from patients as p
group by p.blood_group having count(p.blood_group)>100; 

29.Display doctor names along with their department names.
select d.department_name,doc.doctor_name from departments as d 
join doctors as doc on d.department_id=doc.department_id;

30.Display nurse names along with their department names.
select d.department_name,n.nurse_name from departments as d 
join nurses as n on d.department_id=n.department_id order by department_name ;

31.Display patient names with their appointment details.
select p.patient_name ,a.appointment_id,a.appointment_date,a.appointment_time,a.status from patients as p
join appointments as a on p.patient_id=a.patient_id;

32.Display patient names with admission room details.
select p.patient_name,a.admission_id,a.admission_date,a.discharge_date,a.diagnosis from patients as p 
join admissions as a on p.patient_id =a.patient_id;

33.Display prescription details with patient and doctor names.
select pa.patient_name,d.doctor_name ,p.prescription_id,pre.medicine_id,pre.dosage,pre.duration,pre.quantity from patients as pa
join  prescriptions as p on pa.patient_id=p.patient_id 
join prescription_medicines as pre on p.patient_id=pre. prescription_medicine_id
join doctors as d on d.doctor_id=p.patient_id;

34.Display billing details along with patient names.
select p.patient_name,b.bill_id,b.total_amount,b.bill_date,b.payment_status from patients as p 
join billing as b on p.patient_id=b.patient_id;

35.Find the patient details who have taken appointments with a specific doctor.
select p.patient_name,d.doctor_name ,a.appointment_id,a.appointment_date,a.appointment_time,d.doctor_name from Patients p
join Appointments a on p.patient_id = a.patient_id
join Doctors d on a.doctor_id = d.doctor_id
where d.doctor_name = 'Dr.Arun';

36.Find the doctor who has the highest number of appointments.
select d.doctor_name,count(a.appointment_id) from doctors as d
join appointments as a on d.doctor_id=a.doctor_id group by d.doctor_name order by count(doctor_name) desc ;

37.Find the department having the maximum number of doctors.
select d.department_name,count(doc.doctor_id) from departments as d 
join doctors as doc on d.department_id=doc.department_id
group by d.department_name order by count(doc.doctor_id) desc;

38.Find patients who have never taken an appointment.
select p.patient_name,a.appointment_id,a.status from patients as p 
join appointments as a on p.patient_id=a.patient_id where a.appointment_id is null ;

39.Find medicines that are prescribed more than 10 times.
select m.medicine_id,m.medicine_name,COUNT(pm.medicine_id) AS times_prescribed
from Medicines as m
join Prescription_Medicines as pm on m.medicine_id = pm.medicine_id
group by m.medicine_id, m.medicine_name
having COUNT(pm.medicine_id) > 10
order by times_prescribed DESC;

40.Find the total revenue generated from each payment method (Cash, Card, UPI, Net Banking).
select payment_method,sum(amount_paid) as total_revenue from payments
group by payment_method order by total_revenue desc;